    @Transactional public Map<String,Object> provisionOrder(Long id,String reason,UserPrincipal actor,String ip){Map<String,Object> o=mustOrder(id);if(!"PENDING_PROVISION".equals(s(o.get("status"))))throw err("ORDER_STATUS_INVALID","订单必须处于待开通状态");List<Map<String,Object>> issued=new ArrayList<>();for(Map<String,Object> item:db.orderItems(id)){int n=((Number)item.get("service_count")).intValue();for(int i=0;i<n;i++)issued.add(provisionOne(longv(o.get("customer_id")),id,longv(item.get("id")),longv(item.get("product_id")),item.get("package_id")==null?null:longv(item.get("package_id")),null,(OffsetDateTime)o.get("expected_effective_at"),(OffsetDateTime)o.get("expected_expire_at"),actor,ip));}db.orderStatus(id,"PROVISIONED",actor.userId());audit(actor,"ORDER",id,"PROVISION",required(reason),ip);return Map.of("orderId",id,"services",issued);}
