    private Map<String,Object> provisionOne(Long customerId,Long orderId,Long itemId,Long productId,Long packageId,Long requestedStrategy,OffsetDateTime effective,OffsetDateTime expire,UserPrincipal actor,String ip){Map<String,Object> p=mustActiveProduct(productId);Map<String,Object> k=packageId==null?null:mustActivePackage(packageId,productId);Map<String,Object> st=requestedStrategy==null?db.activeStrategy(productId):null;if(requestedStrategy!=null){Map<String,Object> candidate=db.activeStrategy(productId);if(candidate!=null&&Objects.equals(longv(candidate.get("id")),requestedStrategy))st=candidate;}if(st==null)throw err("SERVICE_STRATEGY_REQUIRED","产品没有可用的已启用资源策略");Map<String,Object> pool=db.primaryPool(longv(st.get("id")));if(pool==null||((Number)pool.get("member_count")).longValue()<=0)throw err("SERVICE_RESOURCE_UNAVAILABLE","资源策略没有可用资源池");OffsetDateTime eff=effective==null?OffsetDateTime.now(ZoneOffset.UTC):effective;OffsetDateTime exp=expire;if(exp==null&&k!=null)exp=eff.plusDays(((Number)k.get("service_days")).longValue());String serviceNo=db.nextServiceNo();String quota=k==null?"{}":j(Map.of("packageId",k.get("id"),"packageCode",k.get("package_code"),"serviceDays",k.get("service_days")));Long sid=db.insertService(serviceNo,customerId,orderId,itemId,productId,packageId,longv(st.get("id")),s(p.get("product_type")),s(p.get("product_json")),k==null?null:s(k.get("package_json")),s(st.get("strategy_json")),quota,eff,exp,actor.userId());db.bind(sid,"POOL",longv(pool.get("id")),"PRIMARY",j(Map.of("poolCode",pool.get("pool_code"))),actor.userId());if("EXCLUSIVE_IP".equals(s(p.get("product_type")))){Map<String,Object> ipr=db.freeExclusiveIp(longv(pool.get("id")));if(ipr==null)throw err("EXCLUSIVE_RESOURCE_UNAVAILABLE","当前资源池没有可分配的独享IP");db.allocateExclusive(sid,"IP",longv(ipr.get("id")),customerId,exp,j(ipr),actor.userId());db.bind(sid,"IP",longv(ipr.get("id")),"OUTBOUND",j(ipr),actor.userId());}if("TUNNEL".equals(s(p.get("product_type")))){Long domain=db.tunnelDomain(productId);if(domain!=null)db.bind(sid,"DOMAIN",domain,"ENTRY","{}",actor.userId());}
        Map<String,Object> cred=issueCredential(sid,serviceNo,s(p.get("product_type")),exp,actor.userId());Map<String,Object> ctx=new LinkedHashMap<>();ctx.put("poolId",pool.get("id"));ctx.put("serviceNo",serviceNo);ctx.put("customerId",customerId);ServiceProvisionAdapter.Result result=adapter.provision(s(p.get("product_type")),sid,ctx);if(!result.success()){db.serviceStatus(sid,"PROVISION_FAILED",result.message(),actor.userId());audit(actor,"SERVICE",sid,"PROVISION_FAILED",result.message(),ip);return Map.of("serviceId",sid,"serviceNo",serviceNo,"status","PROVISION_FAILED","message",result.message());}db.serviceStatus(sid,"ACTIVE",null,actor.userId());audit(actor,"SERVICE",sid,"PROVISION","服务开通成功",ip);Map<String,Object> out=new LinkedHashMap<>();out.put("serviceId",sid);out.put("serviceNo",serviceNo);out.put("status","ACTIVE");out.put("oneTimeCredential",cred);return out;}

