    @Transactional public void suspend(Long id,String reason,UserPrincipal actor,String ip){Map<String,Object>s=mustService(id);if(!"ACTIVE".equals(s(s.get("status"))))throw err("SERVICE_STATUS_INVALID","仅正常服务可暂停");db.freezeCredentials(id);db.serviceStatus(id,"SUSPENDED",null,actor.userId());db.insertChange(db.nextChangeNo(),id,"SUSPEND",j(s),j(Map.of("status","SUSPENDED")),required(reason),"SUCCESS",actor.userId());audit(actor,"SERVICE",id,"SUSPEND",reason,ip);}
    @Transactional public void resume(Long id,String reason,UserPrincipal actor,String ip){Map<String,Object>s=mustService(id);if(!"SUSPENDED".equals(s(s.get("status"))))throw err("SERVICE_STATUS_INVALID","仅暂停服务可恢复");db.activateCredentials(id);db.serviceStatus(id,"ACTIVE",null,actor.userId());db.insertChange(db.nextChangeNo(),id,"RESUME",j(s),j(Map.of("status","ACTIVE")),required(reason),"SUCCESS",actor.userId());audit(actor,"SERVICE",id,"RESUME",reason,ip);}
    @Transactional public OffsetDateTime renew(Long id,int days,String reason,UserPrincipal actor,String ip){if(days<=0)throw err("RENEW_DAYS_INVALID","续费天数必须大于0");Map<String,Object>s=mustService(id);if(Set.of("TERMINATED","PROVISION_FAILED").contains(s(s.get("status"))))throw err("SERVICE_STATUS_INVALID","当前服务不能续费");OffsetDateTime old=(OffsetDateTime)s.get("expire_at");OffsetDateTime base=old==null||old.isBefore(OffsetDateTime.now(ZoneOffset.UTC))?OffsetDateTime.now(ZoneOffset.UTC):old;OffsetDateTime exp=base.plusDays(days);db.renew(id,exp,actor.userId());db.insertChange(db.nextChangeNo(),id,"RENEW",j(Map.of("expireAt",old==null?"":old.toString())),j(Map.of("expireAt",exp.toString(),"days",days)),required(reason),"SUCCESS",actor.userId());audit(actor,"SERVICE",id,"RENEW",reason,ip);return exp;}
    @Transactional public Map<String,Object> terminate(Long id,String reason,UserPrincipal actor,String ip){Map<String,Object>s=mustService(id);if("TERMINATED".equals(s(s.get("status"))))throw err("SERVICE_STATUS_INVALID","服务已终止");ServiceProvisionAdapter.Result ar=adapter.release(s(s.get("product_type")),id,Map.of("serviceNo",s.get("service_no")));if(!ar.success()){Long rid=db.insertRelease(db.nextReleaseNo(),id,"TERMINATE","FAILED","{}","{}",actor.userId(),ar.message());audit(actor,"SERVICE",id,"RELEASE_FAILED",ar.message(),ip);return Map.of("releaseId",rid,"status","FAILED","message",ar.message());}int creds=db.revokeCredentials(id),bindings=db.releaseBindings(id),exclusive=db.recycleExclusive(id);db.serviceStatus(id,"TERMINATED",null,actor.userId());Long rid=db.insertRelease(db.nextReleaseNo(),id,"TERMINATE","SUCCESS",j(Map.of("revoked",creds)),j(Map.of("bindings",bindings,"exclusivePendingRecycle",exclusive)),actor.userId(),null);db.insertChange(db.nextChangeNo(),id,"TERMINATE",j(s),j(Map.of("status","TERMINATED")),required(reason),"SUCCESS",actor.userId());audit(actor,"SERVICE",id,"TERMINATE",reason,ip);return Map.of("releaseId",rid,"status","SUCCESS");}
    @Transactional public Map<String,Object> resetCredential(Long id,String reason,UserPrincipal actor,String ip){Map<String,Object>s=mustService(id);db.revokeCurrentCredential(id);Map<String,Object> c=issueCredential(id,s(s.get("service_no")),s(s.get("product_type")),(OffsetDateTime)s.get("expire_at"),actor.userId());db.insertChange(db.nextChangeNo(),id,"CREDENTIAL_RESET","{}",j(Map.of("credentialReset",true)),required(reason),"SUCCESS",actor.userId());audit(actor,"SERVICE",id,"CREDENTIAL_RESET",reason,ip);return c;}
